  "headline": "Water is not on FDA's shortage list as of 2026-10-21; Corvale East has 2.4 days on hand and the rule recommends buying from American Regent, Inc. (VAI 2024-04-24)",
  "headline_cites": ["D4", "D1", "D5"],
  "sentences": [
    {
      "text": "FDA's records show water is not on the drug shortage list as of 2026-10-21.",
      "cites": ["D4"]
    },
    {
      "text": "Corvale East holds 8 vials of water 1 mL/mL, 10 mL at 3.4 a day, giving 2.4 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 46 vials at 4.3 a day, giving 10.6 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "Corvale Lakeside holds 7 vials at 0.7 a day, giving 9.7 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "The rule's best option is to buy from American Regent, Inc., which is not on FDA's shortage list today and whose plant last inspection was VAI 2024-04-24.",
      "cites": ["D5"]
    },
    {
      "text": "Alternate manufacturers include B. Braun Medical Inc. and Civica, Inc. (Hikma Pharmaceuticals USA Inc., last inspection NAI 2026-05-13), both also not on FDA's shortage list.",
      "cites": ["D6", "D7"]
    }
  ]
}
